function field_label(string $col,array $meta): string {return $meta['labels'][$col]??ucfirst(str_replace('_',' ',$col));}
function relation_label(string $table,string $col,mixed $id,array $modules): string {
 if($id===null)return '—';
 if(!isset($modules[$table]['refs'][$col]))return (string)$id;
 [$refTable,$refPk,$display]=$modules[$table]['refs'][$col];
 if($refTable==='execucao_disciplina'){
  $r=one('SELECT d.nome AS disciplina,c.nome AS curso,e.ano,e.semestre FROM execucao_disciplina e JOIN disciplina d ON d.id_disciplina=e.id_disciplina JOIN curso c ON c.id_curso=e.id_curso WHERE e.id_execucao=?',[$id]);
  return $r? $r['disciplina'].' · '.$r['curso'].' ('.$r['ano'].'/'.$r['semestre'].')' : '#'.$id;
 }
 $r=one("SELECT `$display` AS label FROM `$refTable` WHERE `$refPk`=?",[$id]);
 return $r?(string)$r['label']:'#'.$id;
}
function key_params(array $record,array $meta): array { $r=[];foreach((array)$meta['pk'] as $pk)$r['key_'.$pk]=$record[$pk];return $r; }
